resource "aws_vpc_dhcp_options_association" "pike" {
  dhcp_options_id = aws_vpc_dhcp_options.pike.id
  vpc_id          = "vpc-0c33dc8cd64f408c4"
}

resource "aws_vpc_dhcp_options" "pike" {
  domain_name_servers = ["8.8.8.8", "8.8.4.4"]
  tags = {
    pike = "permissions"
  }
}

responsePreview:
This Terraform configuration creates AWS VPC DHCP options named `pike` using Google DNS servers `8.8.8.8` and `8.8.4.4`, then associates those DHCP options with a VPC. By default, the configuration creates a VPC to make the program immediately deployable, but you may provide an existing VPC ID via `var.vpc_id`. The DHCP options are tagged with `permissions`.

> Note: AWS does not support tags directly on `aws_vpc_dhcp_options_association`; the association resource is still explicitly managed by Terraform.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "Existing VPC ID to associate with the DHCP options. Leave empty to create a new VPC."
  type        = string
  default     = ""
}

variable "vpc_cidr_block" {
  description = "CIDR block for the default VPC created when var.vpc_id is empty."
  type        = string
  default     = "10.0.0.0/16"
}

